var n=`0960-chawanmushi`;var s=`world-0960`;var t=`JP`;var a=`east-asia`;var h=4;var o=49;var r={en:`Chawanmushi`,ua:`Тяванмуші`};var g={en:`Chawanmushi is a Japan dish made with chicken egg, light soy sauce, shiitake mushroom, shrimp. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Тяванмуші, страва кухні країни Японія. Основні складники: куряче яйце, світлий соєвий соус, шиїтаке, креветка. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`chicken-egg`,4,`pcs`],[`dashi-stock`,560,`ml`],[`mirin`,35,`ml`],[`light-soy-sauce`,20,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`shiitake-mushroom`,170,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 9 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 9 хвилин до готовності й м’якості.`,t:[`poaching`],m:9,i:[[`shrimp`,230,`g`],[`chicken-thigh`,180,`g`]]},{en:`Strain the seasoned egg-and-dashi mixture into cups over small cooked filling pieces, cover and steam gently until softly set, not bubbled.`,ua:`Процідіть яєчно-даші суміш у чашки з невеликими шматочками начинки, накрийте й пропарте на малому вогні до ніжного застигання без бульбашок.`,t:[`steaming`],m:20,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,25,`g`]]}];var d={slug:n,id:s,country:`JP`,region:a,servings:4,minutes:49,title:r,text:g,steps:m};export{t as country,d as default,s as id,o as minutes,a as region,h as servings,n as slug,m as steps,g as text,r as title};